import { fileURLToPath } from "node:url";
import Database from "better-sqlite3";
import { type BetterSQLite3Database, drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import * as schema from "./schema.ts";

export type LunasqDatabase = BetterSQLite3Database<typeof schema> & {
  $client: Database.Database;
};

/** Folder with the SQL migrations generated by drizzle-kit (`pnpm db:generate`). */
export const migrationsFolder = fileURLToPath(new URL("../drizzle", import.meta.url));

/** Opens the database in WAL, with foreign keys active and waiting on locks. */
export function openDatabase(path: string): LunasqDatabase {
  const sqlite = new Database(path);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  sqlite.pragma("busy_timeout = 5000");
  return drizzle({ client: sqlite, schema });
}

/**
 * Applies the pending migrations; repeating it has no effect.
 *
 * Foreign keys are turned off while it runs: drizzle executes each migration in a transaction,
 * where `PRAGMA foreign_keys=OFF` has no effect, and those that recreate a parent table (0010 with `tasks`)
 * would cascade-delete their children. It is SQLite's procedure for changing a schema; at the
 * end it is verified that no orphan rows remain.
 */
export function migrateDatabase(db: LunasqDatabase): void {
  const sqlite = db.$client;
  const foreignKeys = sqlite.pragma("foreign_keys", { simple: true }) === 1;
  sqlite.pragma("foreign_keys = OFF");
  try {
    migrate(db, { migrationsFolder });
    const violations = sqlite.pragma("foreign_key_check") as unknown[];
    if (violations.length > 0) {
      throw new Error(`the migration left ${violations.length} rows with broken foreign keys`);
    }
  } finally {
    sqlite.pragma(`foreign_keys = ${foreignKeys ? "ON" : "OFF"}`);
  }
}
